            aOrbiterI = ((aOrbiterI + aOrbiterD) + 0x931C18E9F9DC82DBULL) + aTwistOrbiterUpdateSaltC[((aIndex + 21U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterI) ^ 0xADD89CA780BDB97BULL) ^ aTwistOrbiterUpdateSaltA[((aIndex + 12U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x8CED183026A9291FULL), 27U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterG) + 0x0B5C3AD5C89F7303ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterH) ^ 0xB992DD6299C92F66ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x4E184F72C646A9ABULL), 35U);
