            //
            aWandererK = aWandererK ^ (((RotL64(aScatter, 58U) + aOrbiterC) + RotL64(aOrbiterH, 57U)) + aTwistWandererUpdateSaltE[((aIndex + 13U)) & S_SALT1]);
            aWandererJ = aWandererJ + ((RotL64(aPrevious, 5U) + RotL64(aOrbiterI, 41U)) + aOrbiterG);
            aWandererD = aWandererD ^ ((RotL64(aCross, 27U) + aOrbiterC) + RotL64(aOrbiterF, 34U));
            aWandererA = aWandererA + (((RotL64(aIngress, 35U) + aOrbiterG) + RotL64(aOrbiterD, 5U)) + RotL64(aCarry, 27U));
            aWandererH = aWandererH ^ ((RotL64(aPrevious, 51U) + RotL64(aOrbiterF, 47U)) + aOrbiterD);
