            aOrbiterF = (((aWandererG + RotL64(aIngress, 13U)) + RotL64(aCarry, 27U)) + 0x8293F7CD22D8A3B7ULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterG = ((aWandererC + RotL64(aPrevious, 5U)) + 0xC9C1977595373022ULL) + aTwistOrbiterAssignSaltB[((aIndex + 12U)) & S_SALT1];
