            aOrbiterE = ((aOrbiterE + aOrbiterF) + 0x38F8A14F33BCEEE6ULL) + aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterE) ^ 0xE8886F1E394322E1ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xAD56BCADF387B859ULL), 53U);
