            aCross = (RotL64(aWaterLaneA[((S_BLOCK1 - aIndex + 15153U)) & S_BLOCK1], 11U) ^ RotL64(aWaterLaneD[((S_BLOCK1 - aIndex + 12667U)) & S_BLOCK1], 57U));
