            aScatter = (RotL64(aPrevious, 11U) + RotL64(aCarry, 56U)) + (RotL64(aCross, 37U) ^ RotL64(aIngress, 23U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterC = (aWandererK + RotL64(aScatter, 3U)) + 0x62E736A91A4AEB59ULL;
            aOrbiterA = ((aWandererC + RotL64(aPrevious, 13U)) + 0x1C2346A567E7EEC9ULL) + aTwistOrbiterAssignSaltC[((aIndex + 20U)) & S_SALT1];
            aOrbiterK = (aWandererA + RotL64(aCross, 27U)) + 0x2444EE13F1D9E278ULL;
            aOrbiterJ = ((aWandererE + RotL64(aIngress, 39U)) + RotL64(aCarry, 5U)) + 0x6B0A6AF77D905795ULL;
            aOrbiterI = ((aWandererJ + RotL64(aScatter, 46U)) + RotL64(aCarry, 53U)) + 0x1A1A87ADCF271375ULL;
            aOrbiterG = ((aWandererH + RotL64(aPrevious, 19U)) + 0x638726058C0AED93ULL) + aTwistOrbiterAssignSaltA[((aIndex + 9U)) & S_SALT1];
            aOrbiterH = ((aWandererI + RotL64(aCross, 53U)) + RotL64(aCarry, 37U)) + 0xECC2E9C442CE1B7BULL;
            //
            aOrbiterC = (aOrbiterC + aOrbiterA) + 0x11707D95B8FDD6DCULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterC) ^ 0x6AD2FEA832CB40C0ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x57353F78555EE9FBULL), 35U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterI) + 0x20489A50F6795371ULL) + aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 22U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterJ) ^ 0xE2E9D9834923960FULL) ^ aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 4U)) & S_SALT1];
