            aOrbiterG = (aOrbiterG + aOrbiterK) + 0x421FB3D4C83B7AA9ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterG) ^ 0xAA9E9EEF1048B142ULL) ^ aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xB1F8638166ECC959ULL), 21U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterH) + 0x1753E7D032D17A38ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0x7367E0F55A4737CAULL;
            aOrbiterI = RotL64((aOrbiterI * 0x93333CC3A1CC7671ULL), 51U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterC) + 0x79DEA329A6D2E927ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterI) ^ 0x11B95F9955128856ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x05EC6E291021F78BULL), 43U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterJ) + 0x09988099BE3C3436ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0x95AC9DBC47ACCB1FULL;
            aOrbiterC = RotL64((aOrbiterC * 0xDB8756113E2F0151ULL), 3U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterG) + 0x96A9A63A8A7F1C49ULL) + aTwistOrbiterUpdateSaltE[((aIndex + 27U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterA) ^ 0x2D31A443E85069A2ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x0113CD204BF480E5ULL), 27U);
