            aIngress = (RotL64(aShadowLaneB[((aIndex + 21351U)) & S_BLOCK1], 35U) ^ RotL64(aPoisonLaneD[((aIndex + 16429U)) & S_BLOCK1], 3U));
            aIngress ^= (RotL64(aIceLaneC[((aIndex + 16774U)) & S_BLOCK1], 47U) ^ RotL64(aLightningLaneC[((aIndex + 20686U)) & S_BLOCK1], 24U));
            aIngress = TwistMix64::DiffuseC(aIngress);
