            aCross = (RotL64(aShadowLaneA[((S_BLOCK1 - aIndex + 23187U)) & S_BLOCK1], 57U) ^ RotL64(aPoisonLaneB[((S_BLOCK1 - aIndex + 21011U)) & S_BLOCK1], 21U));
            aCross ^= (RotL64(aWaterLaneB[((S_BLOCK1 - aIndex + 17050U)) & S_BLOCK1], 35U) ^ RotL64(aKeyRowReadA[(((2047U - aIndex) + 21710U)) & W_KEY1], 10U));
            aCross = TwistMix64::DiffuseC(aCross);
            //
            aScatter = (RotL64(aIngress, 3U) + RotL64(aCross, 23U)) + (RotL64(aPrevious, 51U) ^ RotL64(aCarry, 38U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterB = ((aWandererF + RotL64(aScatter, 35U)) + RotL64(aCarry, 41U)) + 0x1C6E37270A0E0916ULL;
            aOrbiterH = ((aWandererH + RotL64(aIngress, 43U)) + 0xB4F1DAEA3C1FC3A3ULL) + aKeyRotateOrbiterAssignSaltD[((aIndex + 9U)) & S_SALT1];
            aOrbiterJ = (aWandererA + RotL64(aPrevious, 21U)) + 0x3B12CDAA5856E03BULL;
            aOrbiterD = ((aWandererG + RotL64(aCross, 13U)) + RotL64(aCarry, 13U)) + 0xDC24949F5878E5EAULL;
            aOrbiterK = (aWandererD + RotL64(aPrevious, 50U)) + 0xD486E6FC4E4D4A8FULL;
            aOrbiterF = ((aWandererI + RotL64(aScatter, 57U)) + 0x5EC244C3620B2ABCULL) + aKeyRotateOrbiterAssignSaltC[((aIndex + 15U)) & S_SALT1];
            aOrbiterG = ((aWandererB + RotL64(aIngress, 29U)) + RotL64(aCarry, 53U)) + 0x3881E021CE58930CULL;
            //
            aOrbiterB = ((aOrbiterB + aOrbiterH) + 0xE26C9DFD0CA39649ULL) + aKeyRotateOrbiterUpdateSaltE[((aIndex + 29U)) & S_SALT1];
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterB) ^ 0x0E8CCC4D444C06AAULL) ^ aKeyRotateOrbiterUpdateSaltD[(((31U - aIndex) + 10U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x60649D333AAB0C11ULL), 3U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterJ) + 0x116861B571296AC1ULL) + aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterH) ^ 0x3AB7C896AC68BD0CULL;
            aOrbiterD = RotL64((aOrbiterD * 0x7C1BEE442F11F4ADULL), 21U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterK) + 0xC2551ECD4A5B19F5ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterD) ^ 0x6C5F6921CBB7CD9BULL;
            aOrbiterF = RotL64((aOrbiterF * 0xC1D286D2CEC991CFULL), 29U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterG) + 0xC7E0292ED0A66EA0ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterF) ^ 0xE36E1FC848148E97ULL) ^ aKeyRotateOrbiterUpdateSaltA[(((31U - aIndex) + 21U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x551207D593626CD5ULL), 47U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterB) + 0x68D30C5E3DED108BULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterG) ^ 0xF2E229FD0BBCD359ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x4A63369A28552C73ULL), 41U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0x56DDBB87CE3E4587ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterK) ^ 0x32B6310B4BD1B94FULL;
            aOrbiterG = RotL64((aOrbiterG * 0xF4DC39EBF1E88B33ULL), 11U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterD) + 0x46D5A1DE28BACBA7ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterJ) ^ 0xB1D15BF124D149A9ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x48F8BAAEDAE04B61ULL), 35U);
            //
            aIngress = aOrbiterK ^ RotL64(aOrbiterD, 21U);
            aIngress = aIngress + (RotL64(aOrbiterF, 27U) ^ aOrbiterB);
            aIngress = aIngress + (RotL64(aOrbiterH, 41U) ^ aOrbiterJ);
            aIngress = aIngress + RotL64(aOrbiterG, 51U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererF = aWandererF ^ ((RotL64(aIngress, 21U) + RotL64(aOrbiterB, 51U)) + aOrbiterF);
            aWandererD = aWandererD + ((RotL64(aCross, 47U) + RotL64(aOrbiterG, 57U)) + aOrbiterH);
            aWandererG = aWandererG ^ (((RotL64(aScatter, 12U) + RotL64(aOrbiterJ, 41U)) + aOrbiterB) + aKeyRotateWandererUpdateSaltC[((aIndex + 18U)) & S_SALT1]);
            aWandererI = aWandererI + ((((RotL64(aPrevious, 35U) + RotL64(aOrbiterD, 34U)) + aOrbiterF) + RotL64(aCarry, 51U)) + aKeyRotateWandererUpdateSaltE[(((31U - aIndex) + 20U)) & S_SALT1]);
            aWandererA = aWandererA ^ ((RotL64(aCross, 53U) + RotL64(aOrbiterH, 13U)) + aOrbiterB);
            aWandererH = aWandererH + (((RotL64(aScatter, 27U) + RotL64(aOrbiterK, 5U)) + aOrbiterF) + RotL64(aCarry, 11U));
            aWandererB = aWandererB ^ ((RotL64(aPrevious, 3U) + aOrbiterD) + RotL64(aOrbiterH, 21U));
            //
            aCarry = aCarry + (RotL64(aWandererD, 10U) ^ aWandererG);
