            aWandererB = aWandererB ^ ((RotL64(aCross, 5U) + aOrbiterC) + RotL64(aOrbiterK, 19U));
            aWandererJ = aWandererJ + ((RotL64(aScatter, 21U) + aOrbiterI) + RotL64(aOrbiterK, 51U));
