            aWandererG = aWandererG + (((RotL64(aPrevious, 47U) + RotL64(aOrbiterB, 57U)) + aOrbiterJ) + RotL64(aCarry, 19U));
            aWandererD = aWandererD ^ ((RotL64(aIngress, 35U) + aOrbiterC) + RotL64(aOrbiterH, 29U));
