            aWandererF = aWandererF ^ (((RotL64(aCross, 29U) + RotL64(aOrbiterJ, 12U)) + aOrbiterK) + aKeyRotateWandererUpdateSaltD[((aIndex + 29U)) & S_SALT1]);
            //
            aCarry = aCarry + (aWandererD ^ RotL64(aWandererJ, 39U));
            aCarry = aCarry + (RotL64(aWandererB, 46U) ^ aWandererH);
