            //
            aOrbiterK = (((aWandererK + RotL64(aIngress, 53U)) + RotL64(aCarry, 51U)) + 0xC0DA82888F810CCCULL) + aKeyRotateOrbiterAssignSaltA[(((31U - aIndex) + 19U)) & S_SALT1];
