            //
            aOrbiterA = ((aOrbiterA + aOrbiterF) + 0x30A6758B2094CB2DULL) + aKeyRotateOrbiterUpdateSaltE[(((31U - aIndex) + 16U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterA) ^ 0x7D02E82E050A9686ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x04EA06F5CFE28E4DULL), 39U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterD) + 0xCE22262A8F15BA49ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterJ) ^ 0x0CBCAA95CC276986ULL) ^ aKeyRotateOrbiterUpdateSaltB[((aIndex + 6U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x4FA9C06D96F13DB7ULL), 47U);
