            aOrbiterG = (aWandererD + RotL64(aScatter, 23U)) + 0x45B41123F21DB447ULL;
            //
            aOrbiterC = ((aOrbiterC + aOrbiterB) + 0xB2F4497604822351ULL) + aKeySpawnOrbiterUpdateSaltC[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterC) ^ 0x5BEC6E2FDE20B558ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x7292A0B610DC28F5ULL), 39U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterF) + 0x23AB7E24CF3710F7ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterB) ^ 0x381D24C7F54A4889ULL) ^ aKeySpawnOrbiterUpdateSaltF[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0xC159B49B67277233ULL), 27U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterD) + 0x0EAF1497ADB61475ULL) + aKeySpawnOrbiterUpdateSaltB[((aIndex + 17U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterI) ^ 0x068F96FCBFBAA0C7ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x025A837C6E39AEB3ULL), 23U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterH) + 0x36F6F7C4825D2822ULL;
