            aOrbiterD = (aOrbiterD + aOrbiterH) + 0x76A429DF9BAEC668ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0xDDF46B98AC2DE07AULL;
            aOrbiterC = RotL64((aOrbiterC * 0x4D82D5783742BED7ULL), 37U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterC) + 0x69C1C1C51E7945CFULL) + aKeySpawnOrbiterUpdateSaltD[((aIndex + 24U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterB) ^ 0x8471543EB0EC3D8CULL;
            aOrbiterI = RotL64((aOrbiterI * 0xEF3763B4A46AED3BULL), 51U);
