            aOrbiterH = (aOrbiterH + aOrbiterI) + 0xA4BA98D893DD4DC7ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterH) ^ 0xB06119EF9CF4ED94ULL) ^ aKeySpawnOrbiterUpdateSaltA[((aIndex + 26U)) & S_SALT1];
