            aWandererE = aWandererE + (((RotL64(aCross, 13U) + aOrbiterB) + RotL64(aOrbiterI, 35U)) + aKeySpawnWandererUpdateSaltA[(((31U - aIndex) + 22U)) & S_SALT1]);
