            //
            aOrbiterK = ((aOrbiterK + aOrbiterC) + 0x74A1A073360387E5ULL) + aKeySpawnOrbiterUpdateSaltF[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterK) ^ 0xBEF08B95F7BEB2ECULL) ^ aKeySpawnOrbiterUpdateSaltA[((aIndex + 9U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x840F3D9883E277B5ULL), 51U);
