            aOrbiterI = (((aWandererJ + RotL64(aIngress, 3U)) + RotL64(aCarry, 47U)) + 0x1D598D832F544556ULL) + aKeySpawnOrbiterAssignSaltD[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterB = (aWandererA + RotL64(aCross, 23U)) + 0xFD56A9D7D5A737A2ULL;
            aOrbiterH = (aWandererD + RotL64(aPrevious, 53U)) + 0x272FD9DDDC0CA5FAULL;
            aOrbiterF = (aWandererE + RotL64(aScatter, 18U)) + 0xC8F3084555916A02ULL;
