            aOrbiterG = RotL64((aOrbiterG * 0xF586CD2A518E3DCDULL), 43U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterJ) + 0xD8CE493F349DAE71ULL) + aKeySpawnOrbiterUpdateSaltD[(((31U - aIndex) + 18U)) & S_SALT1];
