            //
            aOrbiterA = ((aOrbiterA + aOrbiterB) + 0x9931BCE6855482EBULL) + aKeySpawnOrbiterUpdateSaltA[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterA) ^ 0xAAACBCF68F77B20FULL;
            aOrbiterK = RotL64((aOrbiterK * 0xC46B2E2BC6AD89C1ULL), 57U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterI) + 0x42493A64B5E2615EULL;
